layer.css:
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="pitch"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-bg); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 700; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 16px; padding-bottom: 8px; padding-left: 16px; transition: all }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: rgb(0, 0, 238); border-radius: 0px; font-weight: 400; font-style: italic; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: rgb(0, 0, 238); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 700; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"]::after { content: "🔗"; display: inline; margin-left: 8px; vertical-align: middle; color: var(--ryt-text); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 11.2px; font-weight: 700; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-text) }
